/**
 * @file web_auth.cpp
 * @brief Dashboard and OTA passwords: NVS storage, the dashboard login and its sessions, OTA digest checks.
 */

#include "web_auth.h"

#ifdef ARDUINO
#include <Arduino.h>
#include <ESPAsyncWebServer.h>
#include <esp_random.h>
#include <esp_timer.h>
#include <freertos/FreeRTOS.h>
#include <mbedtls/md.h>
#include <nvs.h>
#include <time.h>
#include "config.h"
#include "session_table.h"
#include "web_content.h"  // login_html, generated by scripts/embed_web.py from data/login.html

namespace web_auth {

static constexpr char NVS_NAMESPACE[] = "web_auth";
static constexpr char DASHBOARD_KEY[] = "dashboard";
static constexpr char OTA_KEY[]       = "ota";
static constexpr char SESSIONS_KEY[]  = "sessions";
static constexpr char REALM[]         = "cryocooler";
static constexpr char COOKIE_NAME[]   = "cc_session";
static constexpr char PAGE_HEADER[]   = "X-Dashboard";  // sent by the dashboard page's own requests

static constexpr size_t  TOKEN_CHARS             = 32;   // 128 random bits as hex
static constexpr size_t  PROOF_CHARS             = 64;   // HMAC-SHA256 as hex
static constexpr size_t  nonceSlots              = 4;
static constexpr int64_t nonceLifetimeSeconds    = 60;
static constexpr int64_t temporarySessionSeconds = 24 * 60 * 60;
static constexpr int64_t rememberedSeconds       = static_cast<int64_t>(DASHBOARD_REMEMBER_DAYS) * 24 * 60 * 60;
static constexpr uint8_t maxFailedLogins         = 5;
static constexpr int64_t lockoutSeconds          = 30;
static constexpr int64_t plausibleEpochSeconds   = 1700000000;  // before this the clock isn't set

struct Nonce {
    char    value[TOKEN_CHARS + 1];
    int64_t issuedUptimeSeconds;
    bool    live;
};

/** One remembered session as saved in flash. */
struct StoredSession {
    uint8_t hash[SessionTable::HASH_BYTES];
    int64_t expiresEpochSeconds;
};

// Shared by the loop task (serial commands) and the web server task.
static portMUX_TYPE sLock = portMUX_INITIALIZER_UNLOCKED;
static char         sDashboardPassword[PASSWORD_MAX_CHARS + 1] = "";
static char         sOtaPassword[PASSWORD_MAX_CHARS + 1]       = OTA_DEFAULT_PASSWORD;
static SessionTable sSessions;
static Nonce        sNonces[nonceSlots]       = {};
static size_t       sNextNonceSlot            = 0;
static uint8_t      sFailedLogins             = 0;
static int64_t      sLockedUntilUptimeSeconds = 0;

// ─── Clocks and hashing ───────────────────────────────────────────────────────

/** Seconds since boot; never 0, which SessionTable reads as "unknown". */
static int64_t uptimeSeconds() {
    return esp_timer_get_time() / 1000000 + 1;
}

/** Unix seconds, or 0 until SNTP has set the clock. */
static int64_t epochSeconds() {
    const int64_t now = static_cast<int64_t>(time(nullptr));
    return now > plausibleEpochSeconds ? now : 0;
}

static void randomHex(char* out, size_t chars) {
    for (size_t offset = 0; offset < chars; offset += 8) {
        snprintf(out + offset, 9, "%08lx", static_cast<unsigned long>(esp_random()));
    }
}

static void toHex(const uint8_t* bytes, size_t byteCount, char* out) {
    for (size_t byteIndex = 0; byteIndex < byteCount; ++byteIndex) {
        snprintf(out + byteIndex * 2, 3, "%02x", bytes[byteIndex]);
    }
}

static void sha256(const char* text, uint8_t* hash) {
    mbedtls_md(mbedtls_md_info_from_type(MBEDTLS_MD_SHA256),
               reinterpret_cast<const unsigned char*>(text), strlen(text), hash);
}

/** Compare two strings of the same known length without an early exit. */
static bool sameText(const char* left, const char* right, size_t chars) {
    uint8_t difference = 0;
    for (size_t charIndex = 0; charIndex < chars; ++charIndex) {
        difference |= static_cast<uint8_t>(left[charIndex] ^ right[charIndex]);
    }
    return difference == 0;
}

// ─── Storage ──────────────────────────────────────────────────────────────────

/** Read @p key into @p password; leaves it untouched when missing or invalid. */
static void loadPassword(nvs_handle_t handle, const char* key, char* password) {
    char   stored[PASSWORD_MAX_CHARS + 1];
    size_t storedSize = sizeof(stored);
    if (nvs_get_str(handle, key, stored, &storedSize) == ESP_OK && isValidPassword(stored)) {
        strcpy(password, stored);
    }
}

/** Save @p password under @p key, or erase the key when it is empty. */
static bool storePassword(const char* key, const char* password) {
    nvs_handle_t handle;
    if (nvs_open(NVS_NAMESPACE, NVS_READWRITE, &handle) != ESP_OK) {
        return false;
    }
    esp_err_t result;
    if (password[0] == '\0') {
        result = nvs_erase_key(handle, key);
        if (result == ESP_ERR_NVS_NOT_FOUND) {
            result = ESP_OK;
        }
    } else {
        result = nvs_set_str(handle, key, password);
    }
    const bool stored = (result == ESP_OK) && nvs_commit(handle) == ESP_OK;
    nvs_close(handle);
    return stored;
}

static void copyLocked(char* destination, const char* source) {
    portENTER_CRITICAL(&sLock);
    strcpy(destination, source);
    portEXIT_CRITICAL(&sLock);
}

/** Write the remembered sessions to flash. Flash access stays outside the lock. */
static void saveSessions() {
    SessionTable::Session remembered[SessionTable::SLOTS_PER_KIND];
    portENTER_CRITICAL(&sLock);
    const size_t count = sSessions.copyRemembered(remembered);
    portEXIT_CRITICAL(&sLock);

    StoredSession stored[SessionTable::SLOTS_PER_KIND];
    for (size_t index = 0; index < count; ++index) {
        memcpy(stored[index].hash, remembered[index].hash, SessionTable::HASH_BYTES);
        stored[index].expiresEpochSeconds = remembered[index].expires;
    }
    nvs_handle_t handle;
    if (nvs_open(NVS_NAMESPACE, NVS_READWRITE, &handle) != ESP_OK) {
        return;
    }
    if (count == 0) {
        nvs_erase_key(handle, SESSIONS_KEY);
    } else {
        nvs_set_blob(handle, SESSIONS_KEY, stored, count * sizeof(StoredSession));
    }
    nvs_commit(handle);
    nvs_close(handle);
}

static void loadSessions(nvs_handle_t handle) {
    StoredSession stored[SessionTable::SLOTS_PER_KIND];
    size_t storedSize = sizeof(stored);
    if (nvs_get_blob(handle, SESSIONS_KEY, stored, &storedSize) != ESP_OK) {
        return;
    }
    for (size_t index = 0; index < storedSize / sizeof(StoredSession); ++index) {
        sSessions.add(stored[index].hash, true, stored[index].expiresEpochSeconds);
    }
}

void init() {
    // Fails with NOT_FOUND until the first save creates the namespace.
    nvs_handle_t handle;
    if (nvs_open(NVS_NAMESPACE, NVS_READONLY, &handle) != ESP_OK) {
        return;
    }
    loadPassword(handle, DASHBOARD_KEY, sDashboardPassword);
    loadPassword(handle, OTA_KEY, sOtaPassword);
    loadSessions(handle);
    nvs_close(handle);
}

void clearSessions() {
    portENTER_CRITICAL(&sLock);
    sSessions.clear();
    portEXIT_CRITICAL(&sLock);
    saveSessions();
}

bool setDashboardPassword(const char* password) {
    if (password[0] != '\0' && !isValidPassword(password)) {
        return false;
    }
    if (!storePassword(DASHBOARD_KEY, password)) {
        return false;
    }
    copyLocked(sDashboardPassword, password);
    clearSessions();  // a session from the old password must not outlive it
    return true;
}

bool setOtaPassword(const char* password) {
    if (password[0] != '\0' && !isValidPassword(password)) {
        return false;
    }
    if (!storePassword(OTA_KEY, password)) {
        return false;
    }
    copyLocked(sOtaPassword, password[0] != '\0' ? password : OTA_DEFAULT_PASSWORD);
    return true;
}

bool hasDashboardPassword() {
    return sDashboardPassword[0] != '\0';
}

bool isOtaPasswordDefault() {
    char password[PASSWORD_MAX_CHARS + 1];
    copyLocked(password, sOtaPassword);
    return strcmp(password, OTA_DEFAULT_PASSWORD) == 0;
}

// ─── Sessions ─────────────────────────────────────────────────────────────────

/** Copy the session cookie's value into @p token; false if absent or the wrong length. */
static bool readSessionCookie(AsyncWebServerRequest* request, char* token) {
    const AsyncWebHeader* cookies = request->getHeader("Cookie");
    if (cookies == nullptr) {
        return false;
    }
    const String& header = cookies->value();
    int start = 0;
    while (start < static_cast<int>(header.length())) {
        int end = header.indexOf(';', start);
        if (end < 0) {
            end = header.length();
        }
        String pair = header.substring(start, end);
        pair.trim();
        start = end + 1;

        const int equals = pair.indexOf('=');
        if (equals < 0 || pair.substring(0, equals) != COOKIE_NAME) {
            continue;
        }
        if (pair.length() - equals - 1 != TOKEN_CHARS) {
            return false;
        }
        strcpy(token, pair.c_str() + equals + 1);
        return true;
    }
    return false;
}

static bool hasSession(AsyncWebServerRequest* request) {
    char token[TOKEN_CHARS + 1];
    if (!readSessionCookie(request, token)) {
        return false;
    }
    uint8_t hash[SessionTable::HASH_BYTES];
    sha256(token, hash);

    portENTER_CRITICAL(&sLock);
    const bool live = sSessions.contains(hash, epochSeconds(), uptimeSeconds());
    portEXIT_CRITICAL(&sLock);
    return live;
}

/** Start a session and put its cookie on @p response. */
static void startSession(AsyncWebServerResponse* response, bool remembered) {
    char token[TOKEN_CHARS + 1];
    randomHex(token, TOKEN_CHARS);
    uint8_t hash[SessionTable::HASH_BYTES];
    sha256(token, hash);

    // Without a clock the expiry can't be stamped; such a session is not saved.
    const int64_t epochNow = epochSeconds();
    const bool    saved    = remembered && epochNow != 0;
    portENTER_CRITICAL(&sLock);
    sSessions.add(hash, saved, saved ? epochNow + rememberedSeconds
                                     : uptimeSeconds() + temporarySessionSeconds);
    portEXIT_CRITICAL(&sLock);
    if (saved) {
        saveSessions();
    }

    char cookie[128];
    snprintf(cookie, sizeof(cookie), "%s=%s; Path=/; HttpOnly; SameSite=Strict", COOKIE_NAME, token);
    if (saved) {
        const size_t used = strlen(cookie);
        snprintf(cookie + used, sizeof(cookie) - used, "; Max-Age=%lld",
                 static_cast<long long>(rememberedSeconds));
    }
    response->addHeader("Set-Cookie", cookie);
}

// ─── Login ────────────────────────────────────────────────────────────────────

static void issueNonce(char* nonce) {
    randomHex(nonce, TOKEN_CHARS);
    portENTER_CRITICAL(&sLock);
    Nonce& slot = sNonces[sNextNonceSlot];
    sNextNonceSlot = (sNextNonceSlot + 1) % nonceSlots;
    strcpy(slot.value, nonce);
    slot.issuedUptimeSeconds = uptimeSeconds();
    slot.live                = true;
    portEXIT_CRITICAL(&sLock);
}

/** Use up a nonce; true if it was issued, unused and fresh. */
static bool redeemNonce(const char* nonce) {
    if (strlen(nonce) != TOKEN_CHARS) {
        return false;
    }
    const int64_t now = uptimeSeconds();
    bool redeemed = false;
    portENTER_CRITICAL(&sLock);
    for (Nonce& slot : sNonces) {
        if (!slot.live || !sameText(slot.value, nonce, TOKEN_CHARS)) {
            continue;
        }
        slot.live = false;
        redeemed  = (now - slot.issuedUptimeSeconds) < nonceLifetimeSeconds;
        break;
    }
    portEXIT_CRITICAL(&sLock);
    return redeemed;
}

/** True if @p proof is HMAC-SHA256(key = dashboard password, message = @p nonce) in hex. */
static bool isValidProof(const char* nonce, const char* proof) {
    if (strlen(proof) != PROOF_CHARS) {
        return false;
    }
    char password[PASSWORD_MAX_CHARS + 1];
    copyLocked(password, sDashboardPassword);

    uint8_t mac[SessionTable::HASH_BYTES];
    mbedtls_md_hmac(mbedtls_md_info_from_type(MBEDTLS_MD_SHA256),
                    reinterpret_cast<const unsigned char*>(password), strlen(password),
                    reinterpret_cast<const unsigned char*>(nonce), strlen(nonce), mac);
    char expected[PROOF_CHARS + 1];
    toHex(mac, sizeof(mac), expected);
    return sameText(expected, proof, PROOF_CHARS);
}

static void sendJson(AsyncWebServerRequest* request, int status, const char* body) {
    AsyncWebServerResponse* response = request->beginResponse(status, "application/json", body);
    response->addHeader("Cache-Control", "no-store");
    request->send(response);
}

static void handleLogin(AsyncWebServerRequest* request) {
    if (uptimeSeconds() < sLockedUntilUptimeSeconds) {
        sendJson(request, 429, "{\"error\":\"Too many attempts. Wait 30 seconds.\"}");
        return;
    }
    if (!request->hasParam("nonce", true) || !request->hasParam("proof", true)) {
        sendJson(request, 400, "{\"error\":\"Bad request\"}");
        return;
    }
    const String nonce = request->getParam("nonce", true)->value();
    const String proof = request->getParam("proof", true)->value();

    // The nonce is used up before the proof is checked, so a captured reply can't be replayed.
    if (!hasDashboardPassword() || !redeemNonce(nonce.c_str()) ||
        !isValidProof(nonce.c_str(), proof.c_str())) {
        if (++sFailedLogins >= maxFailedLogins) {
            sFailedLogins             = 0;
            sLockedUntilUptimeSeconds = uptimeSeconds() + lockoutSeconds;
        }
        sendJson(request, 401, "{\"error\":\"Wrong password\"}");
        return;
    }
    sFailedLogins = 0;

    const bool remembered = request->hasParam("remember", true) &&
                            request->getParam("remember", true)->value() == "1";
    AsyncWebServerResponse* response = request->beginResponse(200, "application/json", "{\"ok\":true}");
    response->addHeader("Cache-Control", "no-store");
    startSession(response, remembered);
    request->send(response);
}

static void handleLogout(AsyncWebServerRequest* request) {
    char token[TOKEN_CHARS + 1];
    if (readSessionCookie(request, token)) {
        uint8_t hash[SessionTable::HASH_BYTES];
        sha256(token, hash);
        portENTER_CRITICAL(&sLock);
        const bool wasRemembered = sSessions.remove(hash);
        portEXIT_CRITICAL(&sLock);
        if (wasRemembered) {
            saveSessions();
        }
    }
    AsyncWebServerResponse* response = request->beginResponse(200, "application/json", "{\"ok\":true}");
    char cookie[96];
    snprintf(cookie, sizeof(cookie), "%s=; Path=/; HttpOnly; SameSite=Strict; Max-Age=0", COOKIE_NAME);
    response->addHeader("Set-Cookie", cookie);
    request->send(response);
}

// ─── HTTP checks ──────────────────────────────────────────────────────────────

static bool hasLogin(AsyncWebServerRequest* request, const char* storedPassword) {
    // Digest only: a Basic login would put the password on the network in the clear.
    const AsyncWebHeader* authorization = request->getHeader("Authorization");
    if (authorization == nullptr || !authorization->value().startsWith("Digest ")) {
        return false;
    }
    char password[PASSWORD_MAX_CHARS + 1];
    copyLocked(password, storedPassword);
    return request->authenticate(WEB_AUTH_USERNAME, password, REALM);
}

bool hasDashboardAccess(AsyncWebServerRequest* request) {
    return !hasDashboardPassword() || hasSession(request);
}

bool allowDashboard(AsyncWebServerRequest* request, Route route) {
    if (hasDashboardAccess(request) || hasLogin(request, sDashboardPassword)) {
        return true;
    }
    if (route == Route::Page) {
        request->redirect("/login");
        return false;
    }
    // The page's own requests get a bare 401 so it can go to the login page; a
    // digest challenge there would make the browser show its own password box.
    if (request->hasHeader(PAGE_HEADER)) {
        sendJson(request, 401, "{\"error\":\"Not logged in\"}");
        return false;
    }
    request->requestAuthentication(REALM, true);
    return false;
}

bool isOtaAuthorized(AsyncWebServerRequest* request) {
    return hasLogin(request, sOtaPassword);
}

bool allowOta(AsyncWebServerRequest* request) {
    if (isOtaAuthorized(request)) {
        return true;
    }
    request->requestAuthentication(REALM, true);
    return false;
}

void registerRoutes(AsyncWebServer& server) {
    server.on("/login", HTTP_GET, [](AsyncWebServerRequest* request) {
        if (hasDashboardAccess(request)) {
            request->redirect("/");
            return;
        }
        request->send(200, "text/html", login_html);
    });

    server.on("/api/login/challenge", HTTP_GET, [](AsyncWebServerRequest* request) {
        char nonce[TOKEN_CHARS + 1];
        issueNonce(nonce);
        char body[64];
        snprintf(body, sizeof(body), "{\"nonce\":\"%s\"}", nonce);
        sendJson(request, 200, body);
    });

    server.on("/api/login", HTTP_POST, handleLogin);
    server.on("/api/logout", HTTP_POST, handleLogout);

    // GET /api/session — lets the page tell "logged out" from "board unreachable".
    server.on("/api/session", HTTP_GET, [](AsyncWebServerRequest* request) {
        if (!hasDashboardPassword()) {
            sendJson(request, 200, "{\"passwordSet\":false}");
            return;
        }
        if (hasSession(request) || hasLogin(request, sDashboardPassword)) {
            sendJson(request, 200, "{\"passwordSet\":true}");
            return;
        }
        sendJson(request, 401, "{\"error\":\"Not logged in\"}");
    });
}

} // namespace web_auth

#endif // ARDUINO
